import { useState } from 'react';
import {
  Mail,
  Settings,
  Save,
  RefreshCw,
  ExternalLink,
  ShieldCheck,
  AlertCircle,
  Info,
} from 'lucide-react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Switch } from '@/components/ui/switch';
import { Label } from '@/components/ui/label';
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/components/ui/alert-dialog';
import {
  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from '@/components/ui/accordion';
import { Badge } from '@/components/ui/badge';
import { useEmailSettings } from '@/hooks/useEmailSettings';
import { toast } from 'sonner';
import { UniversalLink } from '@lark-apaas/client-toolkit-lite';
import { useI18n } from '@/i18n/I18nContext';
import PageBreadcrumb from '@/components/PageBreadcrumb';

export default function AdminEmailSettingsPage() {
  const { adminT } = useI18n();
  const { settings, updateSettings, resetSettings, isConfigured } = useEmailSettings();
  const [formData, setFormData] = useState(settings);
  const [testing, setTesting] = useState(false);
  const [resetOpen, setResetOpen] = useState(false);
  const [saving, setSaving] = useState(false);

  const handleSave = () => {
    setSaving(true);
    setTimeout(() => {
      updateSettings(formData);
      setSaving(false);
      toast.success('邮件设置已保存');
    }, 300);
  };

  const handleTest = async () => {
    if (!formData.endpoint) {
      toast.error('请先填写 Formspree Endpoint');
      return;
    }
    setTesting(true);
    try {
      const res = await fetch(formData.endpoint, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Accept': 'application/json',
        },
        body: JSON.stringify({
          name: 'Admin Test',
          company: 'OWELL Admin',
          email: 'test@example.com',
          country: 'Test',
          product: 'Test Product',
          message: 'This is a test email from the OWELL admin panel to verify Formspree integration.',
          source: 'admin-test',
          date: new Date().toISOString(),
          _subject: 'Test - OWELL Inquiry Form',
          _to: formData.recipientEmail,
        }),
      });
      if (res.ok) {
        toast.success('测试邮件已发送，请检查收件箱');
      } else {
        const errText = await res.text().catch(() => '请求失败');
        toast.error(`发送失败: ${res.status} - ${errText.slice(0, 60)}`);
      }
    } catch (err) {
      toast.error(`发送失败: ${err instanceof Error ? err.message : '网络错误'}`);
    } finally {
      setTesting(false);
    }
  };

  const handleReset = () => {
    resetSettings();
    setFormData({
      enabled: false,
      endpoint: '',
      recipientEmail: 'sherwin@tanjeon.com',
    });
    setResetOpen(false);
    toast.success('已重置为默认设置');
  };

  return (
    <div className="space-y-6">
      <PageBreadcrumb
        firstItem={{ label: adminT('admin.dashboard'), href: '/admin/dashboard', icon: 'dashboard' }}
        items={[{ label: adminT('admin.emailSettings') }]}
      />
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-foreground flex items-center gap-2">
            <Mail className="size-6 text-primary" />
            邮件设置
          </h1>
          <p className="text-sm text-muted-foreground mt-1">
            配置询盘自动邮件通知功能，客户提交询盘后自动发送到指定邮箱
          </p>
        </div>
        <Badge variant="outline" className={isConfigured ? 'bg-success/15 text-success border-success/30' : 'bg-muted/50'}>
          {isConfigured ? <ShieldCheck className="size-3 mr-1" /> : <AlertCircle className="size-3 mr-1" />}
          {isConfigured ? '已配置' : '未配置'}
        </Badge>
      </div>

      <Card className="border-border/40 bg-card">
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Settings className="size-5 text-primary" />
            邮件服务配置
          </CardTitle>
          <CardDescription>
            使用 Formspree 第三方表单服务发送询盘邮件，无需后端服务器
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-6">
          {/* 启用开关 */}
          <div className="flex items-center justify-between p-4 rounded-lg bg-muted/30 border border-border/40">
            <div>
              <Label className="text-foreground font-medium text-base">启用自动发邮件</Label>
              <p className="text-sm text-muted-foreground mt-1">
                开启后，客户提交询盘时会自动通过 Formspree 发送邮件通知
              </p>
            </div>
            <Switch
              checked={formData.enabled}
              onCheckedChange={(checked) => setFormData((p) => ({ ...p, enabled: checked }))}
            />
          </div>

          {/* Endpoint */}
          <div className="space-y-2">
            <Label htmlFor="endpoint" className="text-foreground">
              Formspree Endpoint URL
            </Label>
            <Input
              id="endpoint"
              type="url"
              placeholder="https://formspree.io/f/your-form-id"
              value={formData.endpoint}
              onChange={(e) => setFormData((p) => ({ ...p, endpoint: e.target.value }))}
              className="bg-background/60 font-mono text-sm"
            />
            <p className="text-xs text-muted-foreground flex items-start gap-1">
              <Info className="size-3 mt-0.5 shrink-0" />
              在 formspree.io 注册账号并创建表单后获取 Endpoint URL，免费额度 50 次/月
            </p>
          </div>

          {/* 收件邮箱 */}
          <div className="space-y-2">
            <Label htmlFor="recipient" className="text-foreground">
              收件人邮箱
            </Label>
            <Input
              id="recipient"
              type="email"
              placeholder="sherwin@tanjeon.com"
              value={formData.recipientEmail}
              onChange={(e) => setFormData((p) => ({ ...p, recipientEmail: e.target.value }))}
              className="bg-background/60"
            />
            <p className="text-xs text-muted-foreground">
              询盘邮件将发送到此邮箱，支持多个邮箱（用英文逗号分隔）
            </p>
          </div>

          {/* 操作按钮 */}
          <div className="flex flex-col sm:flex-row gap-3 pt-2 border-t border-border/40">
            <Button onClick={handleSave} disabled={saving}>
              {saving ? <RefreshCw className="size-4 mr-1.5 animate-spin" /> : <Save className="size-4 mr-1.5" />}
              保存设置
            </Button>
            <Button variant="outline" onClick={handleTest} disabled={testing || !formData.endpoint}>
              {testing ? <RefreshCw className="size-4 mr-1.5 animate-spin" /> : <Mail className="size-4 mr-1.5" />}
              发送测试邮件
            </Button>
            <Button
              variant="outline"
              className="sm:ml-auto text-destructive hover:text-destructive hover:bg-destructive/10 border-destructive/30"
              onClick={() => setResetOpen(true)}
            >
              <RefreshCw className="size-4 mr-1.5" />
              重置为默认
            </Button>
          </div>
        </CardContent>
      </Card>

      {/* 使用说明 */}
      <Card className="border-border/40 bg-card">
        <CardHeader>
          <CardTitle className="text-base">配置指南</CardTitle>
          <CardDescription>如何获取 Formspree Endpoint 并配置自动邮件</CardDescription>
        </CardHeader>
        <CardContent>
          <Accordion type="single" collapsible className="w-full">
            <AccordionItem value="step1">
              <AccordionTrigger className="text-sm font-medium">
                第一步：注册 Formspree 账号
              </AccordionTrigger>
              <AccordionContent className="text-sm text-muted-foreground space-y-2">
                <p>1. 访问 <UniversalLink to="https://formspree.io" target="_blank" rel="noreferrer" className="text-primary inline-flex items-center gap-1">formspree.io <ExternalLink className="size-3" /></UniversalLink> 并注册账号</p>
                <p>2. 免费计划（Free Plan）每月可发送 50 封邮件，适合小型外贸站点起步</p>
                <p>3. 升级到付费计划可获得更多额度和高级功能</p>
              </AccordionContent>
            </AccordionItem>
            <AccordionItem value="step2">
              <AccordionTrigger className="text-sm font-medium">
                第二步：创建表单并获取 Endpoint
              </AccordionTrigger>
              <AccordionContent className="text-sm text-muted-foreground space-y-2">
                <p>1. 登录后点击 "Create New Form"</p>
                <p>2. 输入表单名称，例如 "OWELL Inquiry"</p>
                <p>3. 创建后会看到 Endpoint URL，格式为 <code className="bg-muted px-1.5 py-0.5 rounded text-xs">https://formspree.io/f/xxxxxxx</code></p>
                <p>4. 复制完整 URL 并粘贴到上方输入框</p>
              </AccordionContent>
            </AccordionItem>
            <AccordionItem value="step3">
              <AccordionTrigger className="text-sm font-medium">
                第三步：设置收件邮箱
              </AccordionTrigger>
              <AccordionContent className="text-sm text-muted-foreground space-y-2">
                <p>方式 A（推荐）：在 Formspree 后台的表单设置中配置收件人邮箱，这样 <code className="bg-muted px-1.5 py-0.5 rounded text-xs">_to</code> 字段可以省略，更安全。</p>
                <p>方式 B：直接在上方"收件人邮箱"中填写，系统会通过 <code className="bg-muted px-1.5 py-0.5 rounded text-xs">_to</code> 字段指定收件人。</p>
                <p>注意：方式 B 需要在 Formspree 设置中启用 "Allow _to override" 选项。</p>
              </AccordionContent>
            </AccordionItem>
            <AccordionItem value="step4">
              <AccordionTrigger className="text-sm font-medium">
                第四步：测试并启用
              </AccordionTrigger>
              <AccordionContent className="text-sm text-muted-foreground space-y-2">
                <p>1. 点击"发送测试邮件"按钮验证配置是否正确</p>
                <p>2. 检查收件邮箱是否收到测试邮件（可能在垃圾箱中）</p>
                <p>3. 开启"启用自动发邮件"开关，保存设置</p>
                <p>4. 完成！客户提交询盘后将自动收到邮件通知</p>
              </AccordionContent>
            </AccordionItem>
            <AccordionItem value="alternatives">
              <AccordionTrigger className="text-sm font-medium">
                其他方案备选
              </AccordionTrigger>
              <AccordionContent className="text-sm text-muted-foreground space-y-2">
                <p><strong>EmailJS</strong> — 类似 Formspree，免费 200 封/月，支持多种 SMTP 服务商</p>
                <p><strong>Getform</strong> — 表单后端服务，免费 50 次/月</p>
                <p><strong>自建后端</strong> — 如有服务器，可使用 Nodemailer + SMTP 自行搭建，无发送次数限制</p>
                <p>所有方案都遵循相同的 API 格式（JSON POST），只需替换 Endpoint URL 即可。</p>
              </AccordionContent>
            </AccordionItem>
          </Accordion>
        </CardContent>
      </Card>

      {/* 重置确认 */}
      <AlertDialog open={resetOpen} onOpenChange={setResetOpen}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>确认重置邮件设置？</AlertDialogTitle>
            <AlertDialogDescription>
              重置后将恢复为默认状态：关闭自动发邮件、清空 Endpoint、收件邮箱重置为 sherwin@tanjeon.com。
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>取消</AlertDialogCancel>
            <AlertDialogAction
              className="bg-destructive hover:bg-destructive/90 text-destructive-foreground"
              onClick={handleReset}
            >
              确认重置
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}
